// RECOMMENDED: Constructor injection with final fields
@Service
class OrderService {
    private final PaymentGateway paymentGateway;
    private final InventoryRepository inventoryRepo;

    // Single constructor - Spring auto-wires without @Autowired since Spring 4.3
    public OrderService(PaymentGateway paymentGateway, InventoryRepository inventoryRepo) {
        this.paymentGateway = paymentGateway;
        this.inventoryRepo = inventoryRepo;
    }

    public void processOrder(Order order) {
        inventoryRepo.reserve(order.getItems());
        paymentGateway.charge(order.getTotal());
    }
}

// AVOID: Field injection with mutable state
@Service
class OrderServiceFieldInjection {
    @Autowired private PaymentGateway paymentGateway; // hidden dependency
    @Autowired private InventoryRepository inventoryRepo; // mutable

    // Dependencies not visible in constructor - harder to test
    public void processOrder(Order order) {
        inventoryRepo.reserve(order.getItems());
        paymentGateway.charge(order.getTotal());
    }
}
