class NotificationService {
    private final EmailSender emailSender;
    private final SmsSender smsSender;
    private PushNotifier pushNotifier; // optional, set via setter

    // Constructor injection - Mockito tries this first
    public NotificationService(EmailSender emailSender, SmsSender smsSender) {
        this.emailSender = emailSender;
        this.smsSender = smsSender;
    }

    // Setter injection - Mockito tries this second if no matching constructor
    public void setPushNotifier(PushNotifier pushNotifier) {
        this.pushNotifier = pushNotifier;
    }

    public void notifyUser(String message) {
        emailSender.send(message);
        smsSender.send(message);
        if (pushNotifier != null) pushNotifier.send(message);
    }
}

@ExtendWith(MockitoExtension.class)
class NotificationServiceTest {
    @Mock EmailSender emailSender;
    @Mock SmsSender smsSender;
    @Mock PushNotifier pushNotifier;

    @InjectMocks NotificationService service; // constructor + setter injection

    @Test
    void shouldSendAllNotifications() {
        service.notifyUser("Test message");
        verify(emailSender).send("Test message");
        verify(pushNotifier).send("Test message"); // injected via setter
    }
}
