@ExtendWith(MockitoExtension.class)
class OrderServiceExplicitTest {
    @Mock private PaymentGateway paymentGateway;
    @Mock private InventoryRepository inventoryRepo;
    @Mock private EmailSender emailSender;

    private OrderService orderService;

    @BeforeEach
    void setUp() {
        // Explicit constructor call - no @InjectMocks magic
        orderService = new OrderService(paymentGateway, inventoryRepo, emailSender);
    }

    @Test
    void shouldProcessOrderWhenPaymentSucceeds() {
        var order = new Order(1L, List.of("item1"), 50.0);
        when(inventoryRepo.reserve(order.getItems())).thenReturn(true);
        when(paymentGateway.charge(order.getTotal())).thenReturn(true);

        var result = orderService.processOrder(order);

        assertThat(result).isTrue();
        verify(emailSender).sendConfirmation(order);
    }

    @Test
    void shouldHandlePaymentFailure() {
        var order = new Order(2L, List.of("item2"), 100.0);
        when(paymentGateway.charge(order.getTotal())).thenReturn(false);

        var result = orderService.processOrder(order);

        assertThat(result).isFalse();
        verify(emailSender, never()).sendConfirmation(any());
    }
}
